quests[8446] = { id = 8446, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shrouded in Nightmare", description = "Corruption seeps from this object.\n\nThere may be a link between this object and the dragons coming forth from the Dream. You must find someone that can decipher the meaning of this item. Perhaps the druids of the Moonglade or Cenarion Hold could assist you further.", progress = "Yes, {race}?", completion = "I must remove the taint from this object. This may shed some light on my recent failures to delve into the Dream. Give it to me.", objectives = "Find someone capable of deciphering the meaning behind the Nightmare Engulfed Object.\n\nPerhaps a druid of great power could assist you.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8447] = { id = 8447, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waking Legends", description = "The waters of Lake Elune'ara should dissolve the nightmares engulfing this object. Give me a moment to perform the cleansing, {name}.", completion = "Take his ring, {name}. It has served its purpose for Malfurion. It shall now serve a new purpose for you...", objectives = "Wait for Keeper Remulos at the Moonglade to cleanse the Nightmare Engulfed Object.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8460] = { id = 8460, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "imbermaw Ally", description = "The Timbermaw are the only furbolg tribe to escape the corruption. However, many other races kill furbolg blindly now, without bothering to see if they are friend or foe. For this reason, the Timbermaw furbolg trust very few.\n\nAre you interested in proving yourself? Drive back the corrupted Deadwood tribe of Felwood and we may one day consider you an ally. You'll find the first Deadwood tribe - warriors, pathfinders and gardeners - to my west.", completion = "We suffer much from the events of the past.  Thank you for what you have done to help protect the Timbermaw.  As a sign of our growing friendship, please accept this humble offering.", objectives = "Grazle wants you to prove yourself by killing 6 Deadwood Warriors, 6 Deadwood Pathfinders, and 6 Deadwood Gardeners. Return to him in southern Felwood near the Emerald Sanctuary when you are done.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8461] = { id = 8461, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "eadwood of the North", description = "There is a camp of Deadwood furbolgs directly to our southwest.  Corruption permeates the camp, and I wish to put an end to it before they become a problem.\n\nThe Deadwood tribe is evil, but it is the effects of the fel that pollutes their minds.  Their hostility is not truly an innate quality, yet they cannot be helped.  It saddens me that we must fight our own brethren.\n\nPlease, {name} - I ask you to do what must be done.  Simply spare me the details; such troublesome images upset me far too much.", completion = "I sense that you have achieved victory.  Victory... such a hollow word considering what had to be done.  Regardless, you've proven yourself to be worthy of our trust.\n\nIt may take some time before the Timbermaw welcome you without hostility within the Hold.  Still, your perseverance will erode any suspicion my brethren may have about you.  So long as you never betray us and raise weapons against us, we will find common ground.", objectives = "Nafien would like you to kill 6 Deadwood Den Watchers, 6 Deadwood Avengers, and 6 Deadwood Shamans. Return to him in northern Felwood near the entrance to Timbermaw Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8462] = { id = 8462, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "peak to Nafien", description = "Perhaps you are capable of handling a larger threat that we Timbermaw face.  You certainly have shown yourself capable here...\n\nAnother of my kind stands guard outside the entrance to Timbermaw Hold, along this road far to the north.  His name is Nafien; while he may appear to be a feral and unsavory beast, fear him not.  He only seeks aid against the malign forces that threaten our home.", completion = "Ah... I have heard the word on the wind about those not of our tribe who seek to ally themselves with the Timbermaw furbolgs.  I welcome you, but you must be warned that my tribe reacts poorly to strangers.\n\nThese are trying times, and we can only trust those who choose to fight the corruption of the land alongside of us... and have proven themselves to us accordingly.  Those who have not done so will be met with open hostility should they enter the Hold.", objectives = "Travel north along the main road in Felwood and speak with the furbolg named Nafien. He stands guard outside the entrance to Timbermaw Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8463] = { id = 8463, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unstable Mana Crystals", description = "A group of Wretched recently raided a supply of unstable mana crystals from one of our arcane sanctums.  If not handled properly, the crystals could explode with enough force to blow a hole into the city walls.\n\nNow, {name}, I don't quite care if they blow themselves up while tapping unstable arcane sources, but the whole incident would make my men look bad.\n\nBring me back any remaining stolen crystals you find; they might still be inside their original crates.", progress = "Did you retrieve the stolen goods yet?", completion = "Excellent work, {name}.", objectives = "Bring back 6 Unstable Mana Crystals to Aeldon Sunbrand at Falconwing Square.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8464] = { id = 8464, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "interfall Activity", description = "The Timbermaw tend to stay to themselves, {name}.  While we do allow safe passage to those we trust, we try to avoid other furbolg tribes if at all possible.\n\nThe Winterfall tribe as of late has become increasingly hostile towards us.  They seem to be in a state of rage, completely engulfed by their own fear and hatred of anything they do not understand.\n\nI must ask you to thin their numbers as to lessen the threat against us.  Seek them out in Winterfall Village, far to the east of here.", completion = "Thank you for what you have done, as saddening as it is.  Accept this as a token of thanks.\n\nI would ask of you to please continue helping us, {name}.  We have very few allies on which to call upon, and without your aid, the threats against my tribe would surely be too much for us to handle alone.", objectives = "Salfa wants you to kill 8 Winterfall Shaman, 8 Winterfall Den Watchers, and 8 Winterfall Ursa. Salfa is located just outside the entrance to Timbermaw Hold in Winterspring.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8465] = { id = 8465, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "peak to Salfa", description = "The threat of corruption comes not only from the Deadwood furbolgs to the south, but also from the east and the Winterfall furbolgs of Winterspring.  If you wish to further aid us, speak with Salfa on the other side of the Hold, by the Winterspring entrance.  Follow the path to the left to reach it.\n\nBe warned - if my kind inside considers you hostile or hated, they will attack.  Travel as quick as you can, avoiding conflict.  To kill a Timbermaw - even in self defense - will only alienate you further.", completion = "Greetings, {class} - I stand guard here as both a speaker for the Timbermaw here in Winterspring and as a defender of the tribe.\n\nOur Winterfall brethren here in this frigid land have fallen under the same corruptive sway as the furbolg of Felwood.  If you've come here offering the Timbermaw furbolgs aid, then we are ready to accept such an offer.", objectives = "Travel through Timbermaw Hold and exit into Winterspring. Speak with Salfa, who stands guard outside the entrance to Timbermaw Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8466] = { id = 8466, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "eathers for Grazle", progress = "While you have proven yourself to me, you may need to continue to work toward proving yourself to the suspicious brethren of my tribe.  To that end, I may be able to continue assisting you.\n\nSome of the Deadwood furbolgs wear a distinctive headdress that may be used as a means of proof in thinning their numbers.  Bring me a feather from any headdresses you acquire; for every set of five you bring me, you will earn recognition amongst the Timbermaw.", completion = "Well done, {name}!  I will make sure that your deeds are known amongst my kind.\n\nRemember to bring any of the feathers you find to me.  I will continue to accept them as long as necessary." }
quests[8467] = { id = 8467, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "eathers for Nafien", progress = "While you have proven yourself to me, you may need to continue to work toward proving yourself to the suspicious brethren of my tribe.  To that end, I may be able to continue assisting you.\n\nSome of the Deadwood furbolgs wear a distinctive headdress that may be used as a means of proof in thinning their numbers.  Bring me a feather from any headdresses you acquire; for every set of five you bring me, you will earn recognition amongst the Timbermaw.", completion = "Well done, {name}!  I will make sure that your deeds are known amongst my kind.\n\nRemember to bring any of the feathers you find to me.  I will continue to accept them as long as necessary." }
quests[8468] = { id = 8468, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Thaelis the Hungerer", description = "The city of Silvermoon hereby issues a reward for the head of Thaelis the Hungerer, notorious Wretched ringleader.  He is wanted for repeated crimes against the general populace of Silvermoon City, including the murder of two city guards.\n\nReport to Sergeant Kan'ren to collect the reward.", progress = "You have something to show me?", completion = "That scoundrel, Thaelis, finally met his fate.  Good job, {name}.  Things should be quiet with the Wretched for a while.", objectives = "Bring Thaelis's Head to Sergeant Kan'ren at Falconwing Square in Eversong Woods.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8469] = { id = 8469, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "eads for Salfa", progress = "You've certainly earned my trust, {name}, but you may need to continue to earn the trust of my untrusting tribe.  There is something you can do to earn that trust.\n\nThe Winterfall are known to carry spirit beads to ward against foul spirits.  These beads have clearly failed in their purpose, as the Winterfall themselves are the agents of corruption.  Bring to me these spirit beads from fallen Winterfall furbolgs; for every set of five you bring me, you will earn recognition amongst the Timbermaw.", completion = "Once again, you prove your honor to us!  I will make sure that your deeds are known amongst my kind.\n\nRemember to bring any of the Winterfall's beads you find to me.  For each set you continue to bring to me, I will speak on your behalf to the tribe." }
quests[8470] = { id = 8470, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deadwood Ritual Totem", description = "You have found one of the Deadwood furbolg's ritual totems.  The totem itself is of non-descript construction, but a palpable sense of despair emanates from it.  If there were any object that might best exemplify the corruption that the Deadwood furbolg suffer under, this item would clearly be it.\n\nOne of the furbolgs inside Timbermaw Hold may have a use for such an item... that is, if you've earned their trust enough for them to speak with you.", progress = "Yes {class}, what can I assist you with?  You walk among us peacefully, though there is assuredly something amiss.  I sense something... something troubling...", completion = "This totem... I recognize it as one of the Deadwood's, but it is thick with the stench of decay.  Whatever foulness has turned our brethren against us is surely present in this object.\n\nYou were wise to bring this to us, {name}.  Perhaps through study and ritual, we can uncover what it is that pollutes the minds of our brethren.  Thank you, friend - please accept these offerings in exchange for your find.", objectives = "Take the Deadwood Ritual Totem inside Timbermaw Hold and see if one of the furbolgs there will find a use for the item. The Timbermaw will not speak with you unless you are of Neutral reputation or greater with them.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8471] = { id = 8471, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Winterfall Ritual Totem", description = "You have found one of the Winterfall furbolg's ritual totems.  The totem itself is of non-descript construction, but it seems to emanate an almost tangible sense of dread and despair.  If many of the Winterfall furbolgs do indeed carry these, it certainly would go a long way in explaining their current condition.\n\nOne of the furbolgs inside Timbermaw Hold may have a use for such an item... that is, if you've earned their trust enough for them to speak with you.", progress = "{class} - you approach us in a peaceful manner, but I sense that you are here on matters that are grave and severe... for both furbolg and {race} alike.  What have you come to tell us?", completion = "This thing... it is in the shape of a Winterfall Ritual Totem, but it has been twisted by forces I cannot begin to comprehend.  Whatever taint that has set the Winterfall against us is surely present in this object.\n\nDivine wisdom has brought both this and you to us, {name}.  We will study this object intently; perhaps one day, the Winterfall will rage against us no longer.\n\nThank you, friend - please accept these offerings in exchange for your benevolence.", objectives = "Take the Winterfall Ritual Totem inside Timbermaw Hold and see if one of the furbolgs there will find a use for the item. The Timbermaw will not speak with you unless you are of Neutral reputation or greater with them.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8472] = { id = 8472, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Major Malfunction", description = "The arcane patrollers crafted by our forefathers to protect the city have fallen into a dangerous state of disrepair.  They fail to recognize us as their masters and will attack us on sight!\n\nEven though they were created many years ago, the arcane cores that power them are still quite useful and valuable to us.  I want you to gather these cores and bring them to me so I can put them to good use again.  You will find the patrollers in the ruined section of Silvermoon, to the northwest.", progress = "Have you succeeded in gathering the arcane cores yet, {name}?", completion = "You've done well, {name}.  With our arcane sanctums not operating at full capacity, these power cores will go a long way in supplementing our needs.", objectives = "Collect 6 Arcane Cores from the Arcane Patrollers that roam the ruins of Silvermoon City and bring them to Magister Jaronis at Falconwing Square in Eversong Woods.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8473] = { id = 8473, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Somber Task", description = "These are difficult times for us, {name}.  It was a very hard decision to burn the woods bordering the Ghostlands to prevent the Scourge's expansion.\n\nThe treants, who have been our friends for years, are now trying to foster the regrowth of the forest along the Scorched Grove.\n\nThis is a painful thing to ask of you, {class}, but we've failed to convince our former allies to cease their endeavors.  I need you to stop them by the only means that remain to us: force.", completion = "So, it is done.  Curse these times that have driven us to desperate measures... and curse our enemy, the Scourge!\n\nLearn this, {name}.  Our lands must be protected, no matter what the cost.  We shall prevail!", objectives = "Slay 10 Withered Green Keepers at the Scorched Grove. Then report back to Larianna Riverwind inside the tower just to the northwest of the Scorched Grove in Eversong Woods.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8475] = { id = 8475, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dead Scar", description = "The black swath of soil that cuts through Eversong Woods is a permanent reminder of the day Arthas led the Scourge into our beloved city.\n\nThis blemish is more than an eyesore as even today it brings Scourge from the Ghostlands to Silvermoon.\n\nGo, {name}, and give my men a hand in killing the mindless undead that walk down the Dead Scar.", progress = "You're back, {name}.  Did you fight off the undead along the Dead Scar yet?", completion = "We don't anticipate the Scourge letting up on their attacks any time soon, but we still appreciate any help we get guarding the Scar.", objectives = "Slay 8 Plaguebone Pillagers and report back to Ranger Jaela on the Dead Scar in Eversong Woods.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8476] = { id = 8476, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Amani Encroachment", description = "Ours are not the vast kingdoms of the humans and orcs.  All we have left of our lands in Azeroth lies mostly before your eyes, {name}.\n\nUntil we can reach Outland, we must defend what little land we have at any cost.\n\nOur uncivilized neighbors to the southeast, the Amani trolls, certainly have a different opinion regarding the ownership of these lands.  Their daily raids are something we can't tolerate anymore.  Go to their settlements, Zeb'Watha and Tor'Watha, and teach them a lesson.", progress = "You'll find Tor'Watha and Zeb'Watha southeast of here.  Come back when you've killed the trolls.", completion = "Good work, {name}.  With more people like you we'll soon restore our lands to their former glory.", objectives = "Lieutenant Dawnrunner at the Farstrider Retreat in Eversong Woods wants you to kill 5 Amani Berserkers and 5 Amani Axe Throwers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8477] = { id = 8477, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Spearcrafter's Hammer", description = "The Amani and the sin'dorei have a long history of mutual dislike and open hostility.  That doesn't prevent me from appreciating a fellow craftsman's work, {name}.\n\nI've come across pieces of Amani weaponry and I must admit I'm impressed by the quality of their work.  It is rumored that Spearcrafter Otembe wields a magical hammer that is so light and well-balanced it allows him to work with great dexterity and efficiency.\n\nIf you bring me this tool I'll use it to craft you a weapon.", progress = "You've brought me Otembe's hammer, {name}?", completion = "There's truth to the rumors, {name}.  This hammer is light and strong at once; I shall manage to complete several of my unfinished projects.  And of course, I'll let you have first pick.", objectives = "Search Tor'Watha to the southeast of the Farstrider Retreat for Spearcrafter Otembe and bring Otembe's Hammer to Arathel Sunforge at the Farstrider Retreat in Eversong Woods.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8478] = { id = 8478, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Choose Your Weapon" }
quests[8479] = { id = 8479, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zul'Marosh", description = "Come closer, mon.  Don't be 'fraid, Ven'jashi not gonna hurt you.\n\nUs Darkspears be mortal enemies of the Amani just like you.  Their boss Zul'Marosh is evil troll.  He give me the bad poison and leave me in this cage to die.\n\nI not scared of dyin', mon.  I seen death in the eye an' I laugh at her.\n\nI cannot die in peace yet, mon.  Not 'til Zul'Marosh be dead too.  You find him 'cross the lake in Zeb'Watha.  I hold this poison off 'til you bring me his big ugly head, mon.  Only then I die peacefully.", progress = "You bring me Zul'Marosh's head?", completion = "Ya, mon.  Zul'Marosh had this comin'.  He burn down Ven'jashi's village.  I kill many Amani before they put me in this cage.  I hide something in the sand, my gift for you now.\n\nAh... ah, the poison... it spread now, mon.  Time to rest...", objectives = "Ven'jashi, the troll prisoner at Tor'Watha, wants you to bring him Chieftain Zul'Marosh's Head. Chieftain Zul'Marosh can be found in Zeb'Watha, across Lake Elrendar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8480] = { id = 8480, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lost Armaments", description = "The Wretched grow bolder every day, {name}.  They've achieved enough coordination to launch an attack on Sunsail Anchorage.\n\nAs if that weren't embarrassing enough, most of our weapons were left behind when they attacked.  Bring me back our armaments so that we may show those ruffians who's boss.", progress = "Did you gather the lost weapons yet?", completion = "Great job, {name}.  Let's show the Wretched what we're made of!", objectives = "Bring 8 Sin'dorei Armaments to Velendris Whitemorn in Eversong Woods.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8481] = { id = 8481, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Root of All Evil", description = "{name}, thanks to you we have devised a way to summon forth the root of all evil for the Winterfall tribe - the corrupting demon that dominates them!\n\nTake this torch to the mouth of Grolnar's personal cave and plant it there.  Doing so will force the demon to reveal itself and investigate.  This is when you and your allies must strike it down!  Only the essence of the fallen demon will begin the lengthy healing process of the Winterfall tribe... and the salvation of Timbermaw Hold.", progress = "You have returned to us, {name}... does this mean that the demon has been slain?", completion = "You've... you've saved us!  Your defeat of the demon Xandivious has ensured the safety of Timbermaw Hold for years to come.  You are truly a hero amongst our kind.\n\nPlease, accept this with our blessing.  Though the healing process will be slow amongst the furbolgs - and the conflict will still go on - you have given the Winterfall something they never had before this day.\n\nThey have a chance at survival.", objectives = "Plant the Demon Summoning Torch in the mouth of Grolnar's cave in the Winterfall furbolg village. Defeat the demon and retrieve the Essence of Xandivious for Gorn One Eye in Timbermaw Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8482] = { id = 8482, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Incriminating Documents", description = "The documents contain detailed maps of different strategic buildings in Eversong Woods.  A diagram of an arcane sanctum is also sketched in good detail.  There seem to be numerous notes in a language you don't recognize.\n\nAs these were carried by a Darnassian spy, it might be a good idea to bring them to the Captain of the Guard - Aeldon Sunbrand.", progress = "You've got something for me?  Let me take a look.", completion = "Are you sure you found these on a night elf?  They're clearly written in Dwarven...\n\nFrom what I can understand of this letter, whoever wrote this did not cause the malfunction, but rather was sent here as a spy to observe the results of it.  They call our endeavors reckless and dangerous... but who?\n\nOf course!  That envoy from Ironforge!  We were fools to trust anyone belonging to the Alliance!", objectives = "Bring the Incriminating Documents to Aeldon Sunbrand at Falconwing Square in Eversong Woods.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8483] = { id = 8483, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dwarven Spy", description = "Listen, {name}.  This is a very delicate situation; even though we've identified the spy, we cannot kill him out in the open.  We cannot try to capture him either as the risk of him escaping is too great.\n\nI want you to go find Prospector Anvilward at the North Sanctum and kill him.  Do this in a quiet manner, we don't want word to spread that we allowed a spy into our city.\n\nBring me his head as proof.  Ironforge will learn not to meddle with the sin'dorei.", progress = "Did you take care of the intruder?", completion = "So, the deed is done.  Excellent job.\n\nWord has been passed to the ranger general and believe me, the dwarves will pay dearly for their treason.\n\nYou've been of great service to your people today, {name}.", objectives = "Bring Prospector Anvilward's Head to Aeldon Sunbrand at Falconwing Square in Eversong Woods.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8484] = { id = 8484, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Brokering of Peace", description = "Your deeds go beyond the tale of a simple hero, {name}.  If you are a representative of your people, then your people are ones we would work to make peace with.\n\nPlease - take this offering to the dwarven king that resides in a mountain of iron; I believe you call this city Ironforge.  In times past, he had tried to make contact with us on behalf of his Alliance.  It is now only fitting to acknowledge you as the key in your Alliance's efforts in brokering peace.", progress = "{class}, you are welcomed in my domain.  Ironforge should always be considered a home to a hero such as yourself.  Now, what business do you have with me?", completion = "Indeed, this is a most fortuitous turn of events.  Were a lasting peace to be made with these creatures, this would certainly give us an advantage in the affairs of Kalimdor... one that the Night Elves cannot support on their own.  I will notify the other leaders of the Alliance of this immediately, and further diplomats will be dispatched!\n\nAs for you, {name}... you have shown courage in both diplomacy and in action.  I thank you, as does the whole of the Alliance.", objectives = "Bring the Timbermaw Offering of Peace to King Magni Bronzebeard in Ironforge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8485] = { id = 8485, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Brokering of Peace", description = "Your deeds go beyond the tale of a simple hero, {name}.  If you are a representative of your people, then your people are ones we would work to make peace with.\n\nPlease - take this offering to the orcish warchief that resides in the lands of Durotar; I believe you call this city Orgrimmar.  In times past, he had tried to make contact with us on behalf of his Horde.  It is now only fitting to acknowledge you as the key in your Horde's efforts in brokering peace.", progress = "The warchief's greetings are bestowed upon you, {class}.  Your deeds make the Horde grow stronger in these troubling times.  Now, what business do you have with me?", completion = "Indeed, this is a most fortuitous turn of events.  Were a lasting peace to be made with these creatures, this would certainly give us an advantage in securing Kalimdor from external threats.  I will notify the other leaders of the Horde of this immediately, and further diplomats will be dispatched!\n\nAs for you, {name}... you have shown courage in both diplomacy and in action.  I thank you, as does the entirety of the Horde.", objectives = "Bring the Timbermaw Offering of Peace to Shok Narnes in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8486] = { id = 8486, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arcane Instability", description = "It's about time that dimwit, Caidanis, sent someone this way.\n\nI warned of the dangers of increasing the load on the West Sanctum!  Now one of our energy converters is destroyed and arcane wraiths are pouring out of the sanctum!\n\nI'm going to need you to take care of these creatures before we send anyone in for repairs.  Make haste!", completion = "Thank you, {name}.  Now that we have the wraiths under control we can send someone in to assess the damage.  Hopefully this wasn't anything permanent.", objectives = "Ley-Keeper Velania wants you to kill 5 Manawraiths and 5 Mana Stalkers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8487] = { id = 8487, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Corrupted Soil", description = "This was a fully functional arcane sanctum before Arthas and his army of Scourge decided to plow through it on their way to Silvermoon.\n\nNow it's as useful to us as any part of the Dead Scar.  The soil is tainted, undead are drawn to it and the energy in the ley lines is completely disrupted.\n\nWhat I want to know, {name}, is whether this taint is reversible or not.  I want you to collect soil samples from this area so I can study them.  Perhaps with time we can set things back to normal.", progress = "Are you done collecting the samples I asked for, {name}?", completion = "Excellent.  I will cast an augmentation enchantment on the samples so I can more clearly analyze the taint on the soil.", objectives = "Apprentice Mirveda at the East Sanctum in Eversong Woods wants you to collect 8 Tainted Soil Samples.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8488] = { id = 8488, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unexpected Results", description = "Something's wrong, {name}.  I sense the presence of Scourge.  Be ready to fight them!", progress = "Is it over?  Are they all gone?", completion = "My endeavors are hopeless, {name}.  The very nature of the soil has been altered... the taint is irreversible.  Thank you for your assistance.  I'll need to ask one last task of you.", objectives = "Speak with Apprentice Mirveda and then protect her from the Scourge ambush.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8489] = { id = 8489, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Intact Converter", description = "This object appears to be one of the arcane converters Ley-Keeper Velania mentioned.  It hasn't been damaged by the fire, perhaps she could find a use for it.", sourceObjective = "Bring the Intact Arcane Converter to Ley-Keeper Velania.This object appears to be one of the arcane converters Ley-Keeper Velania mentioned. It hasn't been damaged by the fire, perhaps she could find a use for it.", sourceObjectiveStatus = "unverified-source-field" }
quests[8490] = { id = 8490, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Powering our Defenses", description = "Ancient runestones once powered a protective barrier across the Eversong border.  Many were destroyed during Arthas' attack; others were stolen.\n\nOf the three that remain, only this one has retained its powers.  The runestone to the east might be salvageable, though.\n\nTake this crystal and instill its energy on the Eastern Runestone.  The process should take but a minute.  Beware though, nearby Scourge will be drawn to it and will seek to destroy it.  Do not let them!", progress = "Have you succeeded in powering the runestone yet, {name}?", completion = "Excellent.  The defenses should hold off the Scourge a bit longer.  Thank you for lending us a hand, {name}.", objectives = "Place the Infused Crystal at the Eastern Runestone and protect it from the Scourge for 1 minute. Return the Infused Crystal to Runewarden Deryan in Eversong Woods for a reward.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8491] = { id = 8491, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pelt Collection", description = "The springpaw that inhabit this region are known for their high quality pelts.  We've even seen night elf scum travel to these lands just to poach them.\n\nOur skirmishes with the Amani have put a bit of a strain on our supply of gear and our rangers don't have much time to hunt for pelts anymore.  If you'd be willing to lend a hand by collecting springpaw pelts, I'd be happy to reward you with a hand-crafted piece of armor.  You'll find springpaw stalkers all around the woods north of here.", progress = "You're back.  Did you bring the pelts?", completion = "These will do perfectly, {name}.  Take this piece of armor as a reward.  I'll be able to make more with the pelts you brought me.", objectives = "Velan Brightoak at Fairbreeze Village in Eversong Woods wants you to bring him 6 Springpaw Pelts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8492] = { id = 8492, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Alliance Needs Copper Bars!", description = "Hey there, {class}, you look fit enough to contribute to the war effort! We need all of the help that we can get here to put together the materiel needed for the Ahn'Qiraj War and it's your lucky day.\n\nI'm collecting copper bars in stacks of twenty. It's for a worthy cause, what do you say? Do you think you could help out the Alliance?", objectives = "Bring 20 Copper Bars to Sergeant Stonebrow at the Military Ward in Ironforge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8493] = { id = 8493, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Alliance Needs More Copper Bars!", description = "Back again {class}? Outstanding! We still need more stacks of copper bars if you can procure them for the Ahn'Qiraj war effort.  Will you help us out?", objectives = "Bring 20 copper bars to Sergeant Stonebrow at the airfield in Dun Morogh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8494] = { id = 8494, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Alliance Needs Iron Bars!", description = "Well hello there, <Mr./Ms.> Fancypants, aren't you a sight for sore eyes. In case you hadn't heard while you were out there \"adventuring\", the Alliance has been gearing up for a war in Ahn'Qiraj and is in need of iron bars... a whole mess of 'em. Bring them to me in stacks of twenty. We can count on you, right, {class}?", objectives = "Bring 20 Iron Bars to Corporal Carnes at the Military Ward in Ironforge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8495] = { id = 8495, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Alliance Needs More Iron Bars!", description = "Back so soon? Stop making me re-evaluate my low opinion of you {class}, you're making me feel all gooey inside. So, as you can tell we still don't have enough iron bars for all of the weapons, armor, steam tanks and whatnot that need building for the bug hunt. Think you have it in you to bring back another stack of twenty iron bars in between all of those trips to Zul'Gurub, or wherever it is that you kids hang out these days?", objectives = "Bring 20 iron bars to Corporal Carnes at the airfield in Dun Morogh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8496] = { id = 8496, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bandages for the Field", description = "Our supply of bandages in the battlefield is running dangerously low after the recent casualties we have incurred.  Obtain a batch of first-aid supplies and deliver them to Windcaller Proudhorn in Cenarion Hold.", objectives = "Bring 30 Heavy Runecloth Bandages, 30 Heavy Silk Bandages and 30 Heavy Mageweave Bandages to Windcaller Proudhorn at Cenarion Hold in Silithus. You must also bring Logistics Task Briefing X in order to complete this quest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8497] = { id = 8497, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Desert Survival Kits", description = "With the arrival of fresh recruits to Cenarion Hold comes the problem of keeping them alive in the desert.  Dehydration as well as numerous poisonous creatures present a serious threat to inexperienced volunteers.  Gather the supplies necessary for a desert survival kit and bring them to Calandrath in Cenarion Hold.", objectives = "Bring 4 Globes of Water, 4 Powerful Anti-Venom and 4 Smoked Desert Dumplings to Calandrath at the inn in Cenarion Hold in Silithus. You must also bring Logistics Task Briefing I in order to complete this quest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8498] = { id = 8498, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twilight Battle Orders", description = "Our scouts have reported new battle orders being issued by the Twilight's Hammer leaders.  The orders are being distributed by Twilight Prophets under heavy escort.  Intercept the orders and bring them to Commander Mar'alith.", progress = "You've brought something for me?", completion = "Excellent.  It's important to stay ahead of the enemy's next move.  This information will allow us to anticipate the Twilight's Hammer's attacks.", objectives = "Obtain the Twilight Battle Orders and bring them Commander Mar'alith at Cenarion Hold in Silithus. You must also bring Tactical Task Briefing X in order to complete this quest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8499] = { id = 8499, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Alliance Needs Thorium Bars!", description = "It is very kind of you to inquire about the needs that the Alliance has. In addition to all of the other collection efforts underway, we are in need of a great quantity of thorium bars, which is the task that I am in charge of. The thorium will be used in the creation of many different things for the war, foremost of which is the construction of a battalion of steam tanks to be airlifted into Silithus as soon as they are completed. Can you aid us in this endeavor, {class}?", objectives = "Bring 20 Thorium Bars to Dame Twinbraid at the Military Ward in Ironforge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8500] = { id = 8500, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Alliance Needs More Thorium Bars!", description = "It is so good to see you again {name}. I hope that you've been doing well. It's true that we are still in need of thorium bars. If you have them to spare I am collecting them for the Ahn'Qiraj war effort.", objectives = "Bring 20 thorium bars to Dame Twinbraid at the airfield in Dun Morogh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8501] = { id = 8501, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Target: Hive'Ashi Stingers", description = "As the war effort mounts, the silithid presence in the area presents an ever increasing threat to our operations.  You've been selected to partake on an assault on Hive'Ashi where your primary target will consist of the airborne Hive'Ashi stingers.\n\nReport back to Commander Mar'alith after your task is completed.", progress = "You wish to tell me something, {name}?", completion = "Excellent work, {name}.  Your part in the attack on Hive'Ashi has been noted.", objectives = "Kill 30 Hive'Ashi Stingers and report back to Commander Mar'alith at Cenarion Hold in Silithus. You must also bring Combat Task Briefing XII in order to complete this quest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8502] = { id = 8502, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Target: Hive'Ashi Workers", description = "As the war effort mounts, the silithid presence in the area presents an ever increasing threat to our operations.  You've been selected to partake on an assault on Hive'Ashi where your primary target will consist of Hive'Ashi workers.\n\nReport back to Commander Mar'alith after your task is completed.", progress = "You have something to tell me, {class}?", completion = "Excellent work, {name}.  Without their workers, the silithid will have a hard time repairing any damage inflicted to their hive's structure.", objectives = "Slay 30 Hive'Ashi Workers and report back to Commander Mar'alith at Cenarion Hold in Silithus. You must also bring Combat Task Briefing III in order to complete this quest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8503] = { id = 8503, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Alliance Needs Stranglekelp!", description = "So, {class}, did I already tell you about all of the fabulous uses stranglekelp has? I did? Oh well... in any case we need a lot of it, and when I say a lot, I mean A LOT! Do you think that you could help us out? I know that it means going without all of those wonderful things that you can make with it, but it's for a good cause!", objectives = "Bring 20 Stranglekelp to Private Draxlegauge at the Military Ward in Ironforge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8504] = { id = 8504, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Alliance Needs More Stranglekelp!", description = "Well hello again there... what was it? Ah yes, {name}! Come to see if I still need more stranglekelp have you? Well, it's your lucky day, because the answer to that very important question is a very affirmative YES! Think you could gather up twenty more?", objectives = "Bring 20 stranglekelp to Private Draxlegauge at the airfield in Dun Morogh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8505] = { id = 8505, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Alliance Needs Purple Lotus!", description = "{class}, the purple lotus is a flower with a plentitude of uses. I am here at the request of the Alliance as an authority on those applications, to preserve the herbs collected and to ensure that their war effort acquires enough purple lotus to sustain whatever function they plan for it.\n\nI would like for you to travel out into the world and return to me with some of these flowers. Is that something that you can do?", objectives = "Bring 20 Purple Lotus to Master Nightsong at the Military Ward in Ironforge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8506] = { id = 8506, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Alliance Needs More Purple Lotus!", description = "Welcome back {class}. Our collection grows, but even now we have a need for additional purple lotus. If it is still within your power to gather more of the herb, I entreat you to do so and return them to me here.", objectives = "Bring 20 purple lotus to Master Nightsong at the airfield in Dun Morogh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8507] = { id = 8507, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Field Duty", description = "Greetings, {name}.  Before I assign you to more involved tasks in the war, you'll need to do your share of field duty.  \n\nYou will find Captain Blackanvil's Ironforge Brigade outside Hive'Zora.\n\nReport to him or his lieutenant, Janela Stouthammer and come back to me.  I shall have a more advanced assignment for you ready.\n\nOh and please do us a favor and stay away from the Orgrimmar Legion.  We've been forced to keep the two forces well apart from one another due to mutual animosity.", progress = "You'll find Captain Blackanvil's force stationed outside Hive'Zora.  Talk to his lieutenant, Janela Stouthammer, if you can't find him.", completion = "Very well, {name}.  I've prepared a set of tasks that should make optimal use of your skills.\n\nWith the continued efforts of you and people like you, our enemy will soon be vanquished once and for all!\n\nShould you require a new mission briefing, return to Captain Blackanvil.", objectives = "Report for duty at the Ironforge Brigade post near Hive'Zora. Prepare your Unsigned Field Duty Papers and obtain Signed Field Duty Papers from Captain Blackanvil and return to Windcaller Kaldon at Cenarion Hold in Silithus.\n\nNote: Healing or casting beneficial spells on a member of the Ironforge Brigade will flag you for PvP.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8508] = { id = 8508, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Field Duty Papers", progress = "I take it you want those papers signed, lad?", completion = "Aye, I suppose that little skirmish will pass as field duty nowadays.  Take these back to Cenarion Hold, I'm sure they'll have a cushy job ready for you.\n\nOff you go!" }
quests[8509] = { id = 8509, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Alliance Needs Arthas' Tears!", description = "I'll keep it simple and to the point, {class}. The Alliance needs to collect a large quantity of Arthas' Tears for the Ahn'Qiraj war effort. Don't ask me what for; I'm just following orders. But I'd like you to gather up as many of the herbs as you can and bring them back to me here. Are you willing to do that?", objectives = "Bring 20 Arthas' Tears to Sergeant Major Germaine at the Military Ward in Ironforge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8510] = { id = 8510, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Alliance Needs More Arthas' Tears!", description = "Ok, so it looks like I still need more Arthas' Tears. I would imagine that you will be able to find them in the general location that you gathered them up for me last time. The quicker we get these, the faster we can start up the offensive against the forces at Ahn'Qiraj.\n\nYou gonna help us out again {class}?", objectives = "Bring 20 arthas' tears to Sergeant Major Germaine at the airfield in Dun Morogh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8511] = { id = 8511, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Alliance Needs Light Leather!", description = "We Stoneflayers have a long history of being skinners, {class}. That's why the Alliance has asked my family to help out with the collection of light leather for the Ahn'Qiraj war effort. I'm here to see to it that the leather is tanned correctly for whatever they want to put it to use for. But we need your help.\n\nSince I have to be here doing that, I need you to go out and collect the skins, returning them to me here. What do you say, <lad/lass>, will you give it a go?", objectives = "Bring 10 Light Leather to Bonnie Stoneflayer at the Military Ward in Ironforge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8512] = { id = 8512, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Alliance Needs More Light Leather!", description = "Good to see you again {name}. It does appear that we need more light leather for the creation of the various war materiel. If you could bring me a stack of ten that would be just perfect.", objectives = "Bring 10 light leather to Bonnie Stoneflayer at the airfield in Dun Morogh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8513] = { id = 8513, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Alliance Needs Medium Leather!", description = "Yes <sir/ma'am>, I have been charged with collecting and tracking all of the medium leather gathered for the war effort. If you have the wherewithal to gather medium leather, from whatever source, then please bring them to me here. I sure would appreciate a hand with this if you can spare the time.", objectives = "Bring 10 Medium Leather to Private Porter at the Military Ward in Ironforge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8514] = { id = 8514, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Alliance Needs More Medium Leather!", objectives = "Bring 10 medium leather to Private Porter at the airfield in Dun Morogh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8515] = { id = 8515, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Alliance Needs Thick Leather!", description = "Oh boy, this is going to be great! {class}, the Ahn'Qiraj war effort is in full swing, and I've been put in charge of keeping track of all of the thick leather that comes in. We'll make tons of things with it, but first we need to get a ton of it. And I mean that literally! That's where you come in.\n\nSo, do you think you can go out there and bring me back a nice, fat stack of thick leather? Do yah, do yah?!", objectives = "Bring 10 Thick Leather to Marta Finespindle at the Military Ward in Ironforge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8516] = { id = 8516, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Alliance Needs More Thick Leather!", objectives = "Bring 10 thick leather to Marta Finespindle at the airfield in Dun Morogh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8517] = { id = 8517, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Alliance Needs Linen Bandages!", description = "The war at Ahn'Qiraj is going to be long and bloody. It is a very wise thing that the Alliance is doing by enlisting the aid of you, and those like you, to build up the materiel necessary before plunging headlong into conflict.\n\nI have been asked to head up the collection of linen bandages for the war, and I am hoping that you are going to assist me in amassing as many as we need. It is no light matter, but at least the linen bandages are the least difficult to create. Are you with us, {class}?", objectives = "Bring 20 Linen Bandages to Sentinel Silversky at the Military Ward in Ironforge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8518] = { id = 8518, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Alliance Needs More Linen Bandages!", description = "Ever am I amazed by the selflessness exhibited when so many would instead turn to selfishness instead. {class}, I am still in need of a number of linen bandages before my assignment here is fulfilled. Will you aid me once more in the collection of those bandages?", objectives = "Bring 20 linen bandages to Sentinel Silversky at the airfield in Dun Morogh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8519] = { id = 8519, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Pawn on the Eternal Board", description = "As you regain your composure and focus your gaze, you notice that something stirs within the crystal. Upon closer inspection, you realize that you are looking into the past... a memory... long forgotten.", completion = "After Staghelm's betrayal, I gathered the shattered pieces of the Scepter of the Shifting Sands and returned here. I had every intention of protecting the scepter from those that would seek to use it to cause harm to our world - thus was born the charge of the Dragonflights.\n\nA scepter divided amongst the four mighty Aspects would prove to be nearly impossible to restore for those willfully seeking chaos... or so I thought. What a fool I was. Even now I am hunted by that cursed flight.", objectives = "Learn all that you can of the past, then speak with Anachronos at the Caverns of Time in Tanaris.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8520] = { id = 8520, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Alliance Needs Silk Bandages!", description = "With the Ahn'Qiraj War looming we need to do everything that we can to see to it that our soldiers have everything that they need. We're doing just that right here. For my part I've been placed in charge of seeing to it that we collect enough silk bandages.\n\nDo you think you can help me out, {class}?", objectives = "Bring 20 Silk Bandages to Nurse Stonefield at the Military Ward in Ironforge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8521] = { id = 8521, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Alliance Needs More Silk Bandages!", objectives = "Bring 20 silk bandages to Nurse Stonefield at the airfield in Dun Morogh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8522] = { id = 8522, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Alliance Needs Runecloth Bandages!", description = "Argue the merits of the war if you will, {class}, but it has already been set in motion. Look around you at your family and friends, and then ask yourself what it is that you can do to see to it that if they are involved, they will have every advantage to survive the conflagration.\n\nTo that end, I am collecting runecloth bandages here from whatever source. Would you like to make a donation?", objectives = "Bring 20 Runecloth Bandages to Keeper Moonshade at the Military Ward in Ironforge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8523] = { id = 8523, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Alliance Needs More Runecloth Bandages!", description = "So it is that we come to discuss pressing matters yet again {class}. Once more I thank you for your previous efforts; it is not everyone who would give so selflessly. But there is still more work to do.\n\n{name}, will you once more collect runecloth bandages and return them to me here?", objectives = "Bring 20 runecloth bandages to Keeper Moonshade at the airfield in Dun Morogh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8524] = { id = 8524, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Alliance Needs Rainbow Fin Albacore!", description = "Hey there, friend! If I were to say to you, 'Don't you think that soldiers should have food to eat like anyone else?', you would of course reply, 'yes'. I agree with you 110%! I'm glad we're in accord. All I need for you to do is to head out there, fish up a whole bunch of raw rainbow fin albacore, and then cook it all up and bring it back to me right here. Mmm, mmm, I can taste it already.", objectives = "Bring 20 Rainbow Fin Albacore to Slicky Gastronome at the Military Ward in Ironforge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8525] = { id = 8525, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Alliance Needs More Rainbow Fin Albacore!", description = "What! You again? Well I'll be a monkey's uncle... except that I'm a gnome. Slicky Gastronome to be precise! So you're back to help out again eh? Well, I can't say as I blame you. Don't you just love the smell of all of that food? <drool>\n\nEnough loitering! Get out there and bring me back more rainbow fin albacore!", objectives = "Bring 20 rainbow fin albacore to Slicky Gastronome at the airfield in Dun Morogh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8526] = { id = 8526, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Alliance Needs Roast Raptor!", description = "Oh, how's it going, {class}? I see that you're interested in maybe gathering up food for the coming war at Ahn'Qiraj? Somehow my dad thought that it would be a good learning experience for me if I were to volunteer to help out here. Big mistake. I don't even like to eat meat.\n\nAnyway, if you feel like it, you could bring me back a lot of roast raptor. Apparently that's what all of the soldiers are going to want.", objectives = "Bring 20 Roast Raptor to Sarah Sadwhistle at the Military Ward in Ironforge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8527] = { id = 8527, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Alliance Needs More Roast Raptor!", description = "Hi again {class}. I can tell you're very excited about all of this. So I suppose you want to bring me another twenty roast raptor. Great. Well you do that. I guess I'll see you when you get back.", objectives = "Bring 20 roast raptor to Sarah Sadwhistle at the airfield in Dun Morogh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8528] = { id = 8528, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Alliance Needs Spotted Yellowtail!", description = "It may not seem heroic to gather up cooked fish, but do not underestimate the value of preparation, young {class}. Soldiers need to eat like anyone else, and we're here to do our part to make sure they have what they need once the war in Ahn'Qiraj commences.\n\nAccordingly, I am stockpiling spotted yellowtail, a versatile source of sustenance that stores well and can be used in many different dishes. It also doesn't have the odor of some other saltwater fish. Are you willing to aid me in this endeavor?", objectives = "Bring 20 Spotted Yellowtail to Huntress Swiftriver at the Military Ward in Ironforge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8529] = { id = 8529, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Alliance Needs More Spotted Yellowtail!", description = "If you're still willing I'd like to send you back out to bring in another haul of spotted yellowtail, {name}. I'd imagine with the expertise you gained the first time out that this catch should be much faster and easier. Are you game?", objectives = "Bring 20 spotted yellowtail to Huntress Swiftriver at the airfield in Dun Morogh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8530] = { id = 8530, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Alliance Needs Singed Corestones!", description = "{class}, I need your help. In the Molten Core there are these stones, singed Corestones to be precise, that we need to harvest for the Ahn'Qiraj war effort. I'm told that our blacksmiths and engineers can put them to good use, so that's where you come in. I need you to go into the Molten Core and gather up as many of these corestones as you can. Of course, you'll want to talk thirty-nine of your closest friends along with you.", objectives = "Bring 50 singed corestones to Commander Stronghammer at the airfield in Dun Morogh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8531] = { id = 8531, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Alliance Needs More Singed Corestones!", description = "Thank you for returning {name}. If you and your friends still have it in you, I need you to return to the Molten Core and continue your singed corestone collection efforts. What do you say?", objectives = "Bring 50 singed corestones to Commander Stronghammer at the airfield in Dun Morogh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8532] = { id = 8532, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Horde Needs Copper Bars!", description = "So glad that you've decided to help out here. Not everyone would, so I need to make sure you understand what it is that I need. Copper bars, not copper ore. We don't have the time or people to do all of the smelting ourselves, so if you would be so kind as to take care of that, your efforts will be duly noted. Is that something that you can handle, {class}?", objectives = "Bring 20 Copper Bars to Miner Cromwell at the Valley of Spirits in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8533] = { id = 8533, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Horde Needs More Copper Bars!", description = "Back so soon? You'll be a real miner in no time {class}. So, you already know the drill; I need you to go out, mine up a mess of copper ore, smelt it into bars and bring it back to me here. I know that's something you're capable of, the question is, are you willing?", objectives = "Bring 20 copper bars to Miner Cromwell in Durotar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8534] = { id = 8534, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hive'Zora Scout Report", description = "We've sent our best scouts deep into the silithid hives to gather intelligence.  Scout Azenel has been watching the silithid movements at Hive'Zora for several days now.  Find her and obtain a written report.  We need to be able to act on that information as soon as possible, {name}.", progress = "You'll find Scout Azenel inside Hive'Zora.  Hurry, {name}!  Time is of the essence.", completion = "Your efforts are greatly appreciated, {name}.  I'll read these scouting reports right away, feel free to go over your next assignment.", objectives = "Contact Cenarion Scout Azenel inside Hive'Zora and return the Hive'Zora Scout Report to Windcaller Proudhorn at Cenarion Hold. You must also bring Tactical Task Briefing VI in order to complete this quest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8535] = { id = 8535, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hoary Templar", description = "The Twilight's Hammer and the elemental nobles they worship present a formidable threat to our operations in Silithus.  With the new enemies we're facing inside Ahn'Qiraj, we cannot afford to lower our guard to our enemies outside.\n\nFind a way to summon and destroy a Hoary Templar and report to Bor Wildmane.", progress = "Is your task done yet, {name}?", completion = "Good job, {name}.  Here's your next assignment.", objectives = "Summon and slay a Hoary Templar and report back to Bor Wildmane in Cenarion Hold. You must also bring Tactical Task Briefing IV in order to complete this quest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8536] = { id = 8536, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Earthen Templar", description = "The Twilight's Hammer and the elemental nobles they worship present a formidable threat to our operations in Silithus.  With the new enemies we're facing inside Ahn'Qiraj, we cannot afford to lower our guard to our enemies outside.\n\nFind a way to summon and destroy an Earthen Templar and report to Bor Wildmane.", progress = "Is your task done yet, {name}?", completion = "Good job, {name}.  Here's your next assignment.", objectives = "Summon and slay an Earthen Templar and report back to Bor Wildmane in Cenarion Hold. You must also bring Tactical Task Briefing III in order to complete this quest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8537] = { id = 8537, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crimson Templar", description = "The Twilight's Hammer and the elemental nobles they worship present a formidable threat to our operations in Silithus.  With the new enemies we're facing inside Ahn'Qiraj, we cannot afford to lower our guard to our enemies outside.\n\nFind a way to summon and destroy a Crimson Templar and report to Bor Wildmane.", progress = "Is your task done yet, {name}?", completion = "Good job, {name}.  Here's your next assignment.", objectives = "Summon and slay a Crimson Templar and report back to Bor Wildmane in Cenarion Hold. You must also bring Tactical Task Briefing II in order to complete this quest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8538] = { id = 8538, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Four Dukes", description = "The links between the Twilight's Hammer and the Abyssal Council are proving to be more important than we had expected.\n\nWe believe the elemental nobles known as the Abyssal Dukes are one of the primary force organizing the Twilight's Hammer cultists.  Find a way to lure the four Abyssal Dukes into our plane of existence and destroy them!\n\nYour dedication and prowess in past assignments have led us to choose you for this particular assignment.  We are certain you will succeed in this endeavor.", objectives = "Find a way to summon and slay the Duke of Cynders, the Duke of Fathoms, the Duke of Zephyrs and the Duke of Shards and report back to Commander Mar'alith in Cenarion Hold. You must also bring Tactical Task Briefing V in order to complete this quest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8539] = { id = 8539, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Target: Hive'Zora Hive Sisters", description = "Reinforcements have been called on to join the assault on Hive'Zora.  You have been selected to target Hive'Zora hive sisters.  Report back to Commander Mar'alith after completing your task.", progress = "You have something to tell me, {class}?", completion = "Excellent work, {name}.  You're a worthy ally.", objectives = "Slay 30 Hive'Zora Hive Sisters and report back to Commander Mar'alith at Cenarion Hold in Silithus. You must also bring Combat Task Briefing V in order to complete this quest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8540] = { id = 8540, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Boots for the Guard", description = "The mounted division of the Cenarion Hold guard is in short supply of ornate mithril boots.  Procure a batch and deliver them immediately to Captain Vish Kozus in Cenarion Hold.", objectives = "Bring 3 Ornate Mithril Boots to Vish Kozus, Captain of the Guard at Cenarion Hold in Silithus. You must also bring Logistics Task Briefing II in order to complete this quest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8541] = { id = 8541, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grinding Stones for the Guard", description = "The Cenarion Hold guard is in short supply of grinding stones.  Procure a batch and deliver them immediately to Captain Vish Kozus in Cenarion Hold.", progress = "You have something for me?", completion = "Excellent.  We were in need of these, {name}.  Good work.", objectives = "Bring 10 Dense Grinding Stones, 10 Solid Grinding Stones and 10 Heavy Grinding Stones to Vish Kozus, Captain of the Guard at Cenarion Hold in Silithus. You must also bring Logistics Task Briefing III in order to complete this quest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8542] = { id = 8542, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Horde Needs Tin Bars!", description = "Lok'tar, {race}, I'm sure you already know that we're going to war at Ahn'Qiraj with the insects. But first the Warchief has decided that we're going to do something called 'prepare'. Though I'd rather be sharpening weapons and hammering armor into shape, I'm proud to have been chosen to be in charge of tin bar collection here. But I cannot do that without your help.\n\nSo I need you to go out and make tin bars and bring them back to me here. I think I'm going to need more than I can count.", objectives = "Bring 20 Tin Bars to Grunt Maug at the Valley of Spirits in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8543] = { id = 8543, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Horde Needs More Tin Bars!", description = "Very good, I see that you are serious about the war. I'm a little edgy waiting for it to start though, which means I'm going to get angry if you don't start bringing in the goods faster. Maybe I can just practice on you instead.\n\nHar! Maybe not, 'cuz then who would bring me back the tin bars?", objectives = "Bring 20 tin bars to Grunt Maug in Durotar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8544] = { id = 8544, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Conqueror's Spaulders", description = "It is said among us that the ornate shoulder armor worn by the mortal races started as an attempt to emulate the wings of a dragon.\n\nBring me the bindings worn by the highest Qiraji leaders and I shall shape them into a set of pauldrons more dreadful than even the wings of Nefarian himself!", progress = "Have you collected the components I require?", completion = "From the materials you bring and from the scales of our fallen Qiraji foes I make you these pauldrons, mortal.  May they grant you the protection you need and may the sight of them strike fear into our enemies.", objectives = "Bring the Qiraji Bindings of Command, 2 Idols of Night, 5 Stone Scarabs and 5 Clay Scarabs to Andorgos in Ahn'Qiraj. You must also attain Neutral reputation with the Brood of Nozdormu to complete this quest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8545] = { id = 8545, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Horde Needs Mithril Bars!", description = "{class}, the war it is comin' and the only thing we can do is prepare for it. That be where you and I can help each other, mon. Ya see, they put me in charge of collectin' all the mithril bars we be needin' ta build for all the things we gonna need. An I still be needin' more!\n\nSo, I be hopin' that you can get out there an mine us up some mithril, then smelt it into bars. Sound like something you can do for us?", objectives = "Bring 20 Mithril Bars to Senior Sergeant T'kelah at the Valley of Spirits in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8546] = { id = 8546, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Horde Needs More Mithril Bars!" }
quests[8547] = { id = 8547, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Welcome!", description = "Welcome to the World of Warcraft!\n\nAs special thanks for purchasing the World of Warcraft Collector's Edition, turn in this gift voucher to Marsilla Dawnstar in Falconwing Square.  You'll then be given a gift: a little companion to join you on your quest for adventure and glory.\n\nThanks again, and enjoy your stay in the World of Warcraft!You will be able to choose one of these rewards:", objectives = "Bring the Falconwing Square Gift Voucher to Marsilla Dawnstar in Falconwing Square.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8548] = { id = 8548, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Volunteer's Battlegear", description = "The badges you collect from performing combat, logistics and tactical assignments for Cenarion Hold are more than just for show, {name}.\n\nYou'd be wise to hold on to them.  As you prove your loyalty to our organization I can offer you some of the gear we reserve for our closest allies in exchange for those badges.", objectives = "Bring 5 Cenarion Combat Badges, 3 Cenarion Logistics Badges and 7 Cenarion Tactical Badges to Vargus at Cenarion Hold in Silithus. You must also attain Friendly reputation with Cenarion Circle to be able to complete this quest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8549] = { id = 8549, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Horde Needs Peacebloom!", description = "It is said that every generation must face a defining trial. I fear the Ahn'Qiraj War will be the crucible in which our mettle is tested. So we prepare, and in so doing find what we are made of.\n\nI have volunteered to help the Horde by gathering as much peacebloom as possible, so that it can be made into potions for the war. I hope that you are here to lend me your aid. If so, then I need you to bring back to me a good quantity of the herb. Will you assist me, {class}?", objectives = "Bring 20 Peacebloom to Herbalist Proudfeather at the Valley of Spirits in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8550] = { id = 8550, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Horde Needs More Peacebloom!" }
quests[8551] = { id = 8551, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Captain's Chest", description = "I used to sail a ship from here all the way to Ratchet, in Kalimdor.  I was a successful captain with a sterling reputation.\n\nUntil...\n\nThose cursed sea giants ruined me!  They smashed my ship, killed my crew, and set me on a lifeboat to Booty Bay.  And one of the giants, Gorlash, stole my Captain's Chest.  He said he wanted it for a snuffbox.  The nerve!\n\nI hear Gorlash wanders the coast east of here.  Find him and get back my chest!  Do that, and you'll have earned a captain's gratitude.", progress = "Ahoy, {name}!  Did you find Gorlash?  That chest was my favorite, and it has a hidden compartment that held my greatest treasures!", completion = "You found it!  Oh happy day, this is!  Thank you, {name}.  Getting back my chest cools some of the fire in me.\n\nBut my revenge isn't complete...", objectives = "Bring Smotts' Chest to Hecklebury Smotts in Booty Bay.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8552] = { id = 8552, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Monogrammed Sash", description = "This fine sash has the letters \"HS\" embroidered along its hem.", progress = "Hello.  Do you have business with me?", completion = "You recovered my sash?  Then...you must have killed Mok'rash the sea giant!  Hooray!\n\nI'm glad the scurvy villain's dead - Mok'rash was one of three sea giants who smashed my ships and killed my crew.\n\nThree times.\n\nYou are a {class} of worth, {name}.", objectives = "Return the Monogrammed Sash to its owner.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8553] = { id = 8553, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Captain's Cutlass", description = "After I lost my first ship to those giants, I bought another.  Named Smotts' Revenge, I filled it with supplies and crew, and set out to find the villains.  I found them, but...they beat me.  They smashed Smotts' Revenge, killed my second crew and set me on another lifeboat.\n\nThis time another of the giants, Negolash, stole my cutlass.\n\nFace Negolash and bring me my cutlass!\n\nSpeak with Sprogger.  He was my cook on the Smotts' Revenge, and survived the last attack.  He can help you find the giant.", completion = "Hello hello, {name}.  Captain told me you're going after Negolash, eh?", objectives = "Speak with Sprogger.After I lost my first ship to those giants, I bought another. Named Smotts' Revenge, I filled it with supplies and crew, and set out to find the villains. I found them, but...they beat me. They smashed Smotts' Revenge, killed my second crew and set me on another lifeboat.\n\nThis time another of the giants, Negolash, stole my cutlass.\n\nFace Negolash and bring me my cutlass!\n\nSpeak with Sprogger. He was my cook on the Smotts' Revenge, and survived the last attack. He can help you find the giant.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8554] = { id = 8554, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Facing Negolash", description = "Negolash is a hungry giant.\n\nWhen the giants destroyed our ship, Negolash went straight for my kitchen.  He wasn't hungry for crew like the other giants.  Negolash wanted wine...and my Barbecued Buzzard Wings.  They're my specialty, and I had to go all the way to the Badlands for the recipe!\n\nIf you want to lure the giant, then get some wine and a heap of buzzard wings.  Put them in our old lifeboat, southeast of here along the coast.  When Negolash smells all that food, he'll come for sure!", progress = "Did you get my cutlass, {name}?", completion = "You got my cutlass from Negolash!  I can't believe my fortune, {name}!  Meeting you has turned my luck to the better, make no mistake there!\n\nThank you!  And if I ever get a new ship and you're looking to sail the seas, you would be my honored guest.", objectives = "Bring 10 Barbecued Buzzard Wings and 5 bottles of Junglevine Wine to Captain Smotts' Lifeboat.\n\nKill Negolash, and bring Smotts' Cutlass to Captain Smotts in Stranglethorn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8555] = { id = 8555, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Charge of the Dragonflights", objectives = "Eranikus, Vaelastrasz, and Azuregos... No doubt you know of these dragons, mortal. It is no coincidence, then, that they have played such influential roles as watchers of our world.\n\nUnfortunately (and my own naivety is partially to blame) whether by agents of the Old Gods or betrayal by those that would call them friend, each guardian has fallen to tragedy. The extent of which has fueled my own distrust towards your kind.\n\nSeek them out... And {race}, prepare yourself for the worst.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8556] = { id = 8556, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Signet of Unyielding Strength", description = "The rings worn by the Qiraji lieutenants are rumored to grant them formidable abilities.  The corrupted gems that adorn them could, in theory, be swapped out with more pure materials to create uncorrupted versions of the rings.\n\nThe gems that adorn Qiraji idols would work quite well, as their quality is superior.\n\nBring me the ring and idols and I'll create a powerful ring for you, {class}.", progress = "Did you bring me the ring and materials, {name}?", completion = "I will swap the gem on the ring for you.  You'll find the effect is much more... agreeable.", objectives = "Bring 1 Qiraji Magisterial Ring, 2 Lambent Idols, 5 Bronze Scarabs and 5 Ivory Scarabs to Windcaller Yessendra in Silithus. You must also attain Honored reputation with Cenarion Circle to complete this quest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8557] = { id = 8557, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drape of Unyielding Strength", description = "I'm glad to hear you're aiding us in our attack on Ahn'Qiraj, {name}.  I can make you a protective item that'll be of assistance in the fight against our enemy, {class}.\n\nI shall need a Qiraji drape, which I'll resize for you of course.  I'll also need idols and scarabs which I'll use to create a suitable clasp.\n\nI promise you won't be disappointed.", progress = "Did you bring the materials for the cloak, {name}?", completion = "Ah yes... this drape is immaculate.\n\nTake this cloak, {name}.  May it protect you from the foul magic of the Qiraji.", objectives = "Bring 1 Qiraji Martial Drape, 2 Onyx Idols, 5 Silver Scarabs and 5 Bone Scarabs to Keyl Swiftclaw in Silithus. You must also obtain Revered reputation with Cenarion Circle to complete this quest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8558] = { id = 8558, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sickle of Unyielding Strength", description = "The Qiraji and their servants wield items made with the rarest and finest materials: bones from gargantuan ancient creatures, gems from the depths of the earth, metals pure and strong.\n\nJust the sight of Qiraji artifacts fills me with an urge to practice my craft with their shattered and smelted pieces.  Prove your allegiance to the Circle, {name}, and I will make you a powerful weapon from the finest Qiraji materials.", progress = "Did you bring me the components I require, {name}?", completion = "You've done well, {class}.  This is a masterwork hilt... the balance is perfect.\n\nTake your weapon, {name}.  Wield it with great confidence and vanquish our enemies!", objectives = "Bring 1 Qiraji Spiked Hilt, 2  Alabaster Idols, 5 Crystal Scarabs and 5 Stone Scarabs to Warden Haro in Silithus. You must also attain Exalted reputation with Cenarion Circle to complete this quest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8559] = { id = 8559, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Conqueror's Greaves", description = "Qiraji magic is strong and ancient.  The most powerful qiraji wield items of such might, they'd give pause even to a dragon.\n\nBring me the qiraji bindings of command and other minor components by and I'll create a set of powerful boots for you.\n\nYou will find them useful in the fight against the enemy.", progress = "You've acquired the items I requested, {name}?", completion = "You've done well, {name}.  You've proven you're no ordinary mortal.\n\nI give you these with the confidence they'll aid you in crushing the vile qiraji.", objectives = "Bring the Qiraji Bindings of Command, 2 Idols of War, 5 Ivory Scarabs and 5 Gold Scarabs to Kandrostrasz in Ahn'Qiraj. This quest also requires Neutral faction with the Brood of Nozdormu.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8560] = { id = 8560, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Conqueror's Legguards", description = "You seek to prove your worth to my kind, mortal?  Very well, perhaps we can be of mutual assistance.\n\nThe ancient sandworm, Ouro, is a being of legendary power.  He is rumored to have been created by the Old God himself as a mockery of life.\n\nHis skin is unnatural... thick, nearly impregnable, yet it's flexible and allows him to move with the speed and grace of a much smaller creature.\n\nBring me a sample of his skin along with other minor components and I shall craft you leggings of great power.", progress = "Did you bring the components I require, {name}?", completion = "Yes... the worm's hide will make for an excellent protective layer.  Combined with the strongest parts from the Qiraji we've destroyed on our way here, this should make for a formidable piece of armor.  May it aid you in facing the unspeakable horrors that await inside!", objectives = "Bring Ouro's Intact Hide, 2 Idols of Death, 5 Bronze Scarabs and 5 Ivory Scarabs to Kandrostrasz inside Ahn'Qiraj. You must also attain Friendly reputation with the Brood of Nozdormu to complete this quest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8561] = { id = 8561, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Conqueror's Crown", description = "The Twin Emperors... their incessant whispers are slowly taking a toll on my sanity.  They mock me, knowing I cannot step further into their domain to save my brother Arygos.\n\nIn my visions I see their monstrous faces adorned by powerful crowns.  But I will have my revenge... I will transmute these symbols of Qiraji power to ones better suited to our needs.\n\nBring me the components I require, {name}.  I will give you a headpiece of unmatched power.", progress = "Did you bring me the components I asked for, {name}?", completion = "You've succeeded!  The whispers from the Twin Emperors have ceased.\n\nTake this as a reward.  The mere sight of it will strike fear in the hearts of the Qiraji... it shall remind them of their fallen leaders and of the mortal that slew them.", objectives = "Bring Vek'nilash's Circlet, 2 Idols of the Sun, 5 Stone Scarabs and 5 Crystal Scarabs to Andorgos in Ahn'Qiraj. You must also attain Friendly reputation with the Brood of Nozdormu to complete this quest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8562] = { id = 8562, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Conqueror's Breastplate", description = "The unmentionable Old God slowly awakens from his slumber beneath Ahn'Qiraj.  The terrible fate that awaits Azeroth could come in days or years; time has no meaning for beings of his power.\n\nWhen the stars are favorable, he will lash out against all living beings with terrible wrath.  You must find him before then and find a way to bring his existence to an end.\n\nDo this and bring me a piece of his husk.  I shall grant you armor no mortal has ever worn... armor fit for one who has slain a god!", progress = "At his dwelling in Ahn'Qiraj, dread C'Thun awaits in slumber.", completion = "I did not expect you to return from your attempt, {name}.\n\nYou've fulfilled a destiny greater than that of most immortal beings.\n\nBy slaying C'Thun you've not only saved all of Azeroth, you've also tipped the scales of cosmic events beyond your comprehension.\n\nAccept this breastplate as a symbol of the glory and burden that will come as a consequence of your actions.\n\nMay its power aid you in the challenges that await you, god-slayer!", objectives = "Bring the Carapace of the Old God, 2 Idols of War, 5 Silver Scarabs and 5 Bone Scarabs to Vethsera inside Ahn'Qiraj. You must also attain Honored reputation with the Brood of Nozdormu to complete this quest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8563] = { id = 8563, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warlock Training", description = "As you advance within your class, you will want to take advantage of the training that your class trainer can provide you.  For young warlocks here on Sunstrider Isle, your trainer is Summoner Teli'Larien.  Speak with Summoner Teli'Larien and see what training he has available for you.  The things he will teach do have a cost, so bring some coin with you.\n\nYour trainer - as with all the trainers on Sunstrider Isle - is inside the Sunspire on the lower level.", completion = "{name} - your name has passed my ears as one seeking out a master in the ways of the {class}.  You look capable enough, but I seek more than just looks from my students.  You must be ready to delve where others fear to look to gain your power.  I will teach you, but I will not tolerate failure.\n\nThere will be monetary costs associated with your training, but you should be more concerned with the cost your mind is willing to make.  If you are ready, we shall begin.", objectives = "Speak with Summoner Teli'Larien - the Warlock class trainer - inside the Sunspire on Sunstrider Isle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8564] = { id = 8564, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Priest Training", description = "As you advance within your class, you will want to take advantage of the training that your class trainer can provide you.  For young priests here on Sunstrider Isle, your trainer is Matron Arena.  Speak with the matron and see what training she has available for you.  The things she will teach do have a cost, so bring some coin with you.\n\nMatron Arena - as with all the trainers on Sunstrider Isle - is inside the Sunspire on the lower level.", completion = "Welcome, {name} - I am Matron Arena.  I offer my services to those who seek to learn the ways of the {class}.  Such a path is often misconstrued as a path of pacifism; for we blood elves, this couldn't be further from the truth.  While we do mend both bone and spirit, we also act as a fist of vengeance for those who would transgress against us.\n\nI will train you, but all I ask is that you cover any training costs that may come up, and that you learn with an open mind.  If you agree to this, we may begin.", objectives = "Speak with Matron Arena - the Priest class trainer - inside the Sunspire on Sunstrider Isle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8565] = { id = 8565, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Past Victories in Arathi" }
